"""Additions to the OpenAPI spec generated by FastAPI."""

import ast
import inspect
import textwrap
from enum import Enum
from typing import Iterator


def enum_member_docs(enum_class: type[Enum]) -> dict[str, str]:
    """Docstrings of the members of an enum, by member name.

    Python drops the string literals following the member assignments, so
    they are read from the source of the class.
    """
    try:
        source = textwrap.dedent(inspect.getsource(enum_class))
    except (OSError, TypeError):
        # no class statement, e.g. enums created from database values at startup
        return {}
    body = ast.parse(source).body[0].body
    docs = {}
    for statement, following in zip(body, body[1:]):
        if isinstance(statement, ast.Assign) and len(statement.targets) == 1:
            target = statement.targets[0]
        elif isinstance(statement, ast.AnnAssign):
            target = statement.target
        else:
            continue
        if (
            isinstance(target, ast.Name)
            and isinstance(following, ast.Expr)
            and isinstance(following.value, ast.Constant)
            and isinstance(following.value.value, str)
        ):
            docs[target.id] = inspect.cleandoc(following.value.value)
    return docs


def _enum_classes(base: type[Enum] = Enum) -> Iterator[type[Enum]]:
    for subclass in base.__subclasses__():
        yield subclass
        yield from _enum_classes(subclass)


def add_enum_descriptions(spec: dict) -> dict:
    """Add the docstrings of enum members to their schemas as `x-enumDescriptions`.

    The schemas are matched to the loaded enum classes by name and values.
    The extension is rendered by e.g. Redoc and docusaurus-openapi-docs.
    """
    classes: dict[str, list[type[Enum]]] = {}
    for enum_class in _enum_classes():
        classes.setdefault(enum_class.__name__, []).append(enum_class)
    for name, schema in spec.get("components", {}).get("schemas", {}).items():
        if "enum" not in schema:
            continue
        for enum_class in classes.get(name, []):
            members = list(enum_class)
            if [member.value for member in members] != schema["enum"]:
                continue
            docs = enum_member_docs(enum_class)
            descriptions = {
                str(member.value): docs[member.name]
                for member in members
                if member.name in docs
            }
            if descriptions:
                schema["x-enumDescriptions"] = descriptions
            break
    return spec
